<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {api,native,state} from './native.js';
import {calendarView,clock,dateKey,duration} from '../../../packages/playtime/view.mjs';
import '../../../packages/playtime/calendar.css';
import Icon from './Icon.vue';import AppOverlay from './AppOverlay.vue';import AppSelect from './AppSelect.vue';
const props=defineProps({request:Object});
const source=ref('local'),data=ref(null),error=ref(''),loading=ref(false),picked=ref(dateKey()),detail=ref(false),detailData=ref(null),detailError=ref(''),detailLoading=ref(false),board=ref(false),week=ref(0),ranking=ref(null),boardError=ref(''),boardLoading=ref(false),period=ref(182),host=ref(),narrow=ref(true);
let generation=0,detailGeneration=0,boardGeneration=0,observer;
const view=computed(()=>calendarView(data.value?.days||[],dateKey(),narrow.value?91:period.value)),day=computed(()=>data.value?.days?.find(v=>v.date===picked.value)),loggedIn=computed(()=>state.connected&&!!state.selectedProfile?.id);
async function load(){const id=++generation;loading.value=true;error.value='';data.value=null;try{const result=source.value==='local'?await native('gamePlaytime'):loggedIn.value?await api('/api/playtime/calendar'):null;if(id===generation)data.value=result;}catch(e){if(id===generation)error.value=e.message;}finally{if(id===generation)loading.value=false;}}
async function loadDetail(){const id=++detailGeneration;detailData.value=null;detailError.value='';if(!detail.value||source.value!=='server'||!loggedIn.value){detailLoading.value=false;return;}detailLoading.value=true;try{const result=await api('/api/playtime/detail?date='+picked.value);if(id===detailGeneration)detailData.value=result;}catch(e){if(id===detailGeneration)detailError.value=e.message;}finally{if(id===detailGeneration)detailLoading.value=false;}}
async function loadBoard(){const id=++boardGeneration;boardError.value='';ranking.value=null;if(!board.value||!loggedIn.value){boardLoading.value=false;return;}boardLoading.value=true;try{const result=await api('/api/playtime/leaderboard'+(week.value?'?week='+week.value:''));if(id===boardGeneration)ranking.value=result;}catch(e){if(id===boardGeneration)boardError.value=e.message;}finally{if(id===boardGeneration)boardLoading.value=false;}}
watch([source,()=>state.selectedProfile?.id,loggedIn],load,{immediate:true});watch([detail,picked,source,loggedIn],loadDetail);watch([board,week,loggedIn],loadBoard);
watch(()=>props.request,value=>{if(value){week.value=Number(value.week)||0;board.value=true;}},{immediate:true});
function focus(){if(!document.hidden)void load();}
onMounted(()=>{observer=new ResizeObserver(()=>narrow.value=host.value?.clientWidth<430);observer.observe(host.value);window.addEventListener('focus',focus);});
onUnmounted(()=>{generation++;detailGeneration++;boardGeneration++;observer?.disconnect();window.removeEventListener('focus',focus);});
</script>
<template>
 <section ref="host" class="card play-calendar mobile-play-calendar">
  <div class="pt-toolbar"><h2>游玩日历</h2><div class="calendar-actions"><button class="soft-button" @click="board=true"><Icon name="trophy"/>每周时长榜</button><button class="icon-button" aria-label="刷新游玩日历" :disabled="loading" @click="load"><Icon name="refresh"/></button></div></div>
  <div class="pt-tabs" aria-label="日历统计来源"><button :aria-pressed="source==='local'" @click="source='local'">本机游玩</button><button :aria-pressed="source==='server'" @click="source='server'">服务器在线</button></div>
  <div class="pt-stats"><div v-for="([label,seconds]) in [['今日',view.summary.today],['本周',view.summary.week],['本月',view.summary.month]]" :key="label"><small>{{label}}</small><strong>{{data?duration(seconds):'—'}}</strong></div></div>
  <div v-if="error" class="pt-alert" role="status"><span>{{source==='server'?'暂未获取服务器记录，请确认社区服务已更新。':'暂未读取本机记录。'}} {{error}}</span><button class="text-button" @click="load">重试</button></div><p v-else-if="source==='server'&&!loggedIn" class="pt-hint">连接社区后查看跨设备的服务器在线记录。</p><p v-else-if="loading&&!data" class="pt-hint">正在读取游玩记录…</p>
  <div class="pt-toolbar"><span class="pt-hint">{{narrow?'最近 13 周':period===364?'最近一年':'最近 26 周'}} · {{view.summary.activeDays}} 天有记录</span><div v-if="!narrow" class="pt-tabs"><button :aria-pressed="period===182" @click="period=182">半年</button><button :aria-pressed="period===364" @click="period=364">一年</button></div></div>
  <div class="pt-heat-scroll"><div class="pt-heat"><div class="pt-months" :style="{gridTemplateColumns:`repeat(${view.columns.length},minmax(0,1fr))`}"><span v-for="(month,index) in view.months" :key="index" :style="{gridColumn:`${month.column+1} / span ${Math.min(3,view.columns.length-month.column)}`}">{{month.label}}</span></div><div class="pt-weekdays"><span v-for="(label,index) in ['一','','三','','五','','日']" :key="index">{{label}}</span></div><div class="pt-grid" :style="{gridTemplateColumns:`repeat(${view.columns.length},minmax(0,1fr))`}" aria-label="每日游玩时长"><button v-for="cell in view.columns.flat()" :key="cell.date" :disabled="!cell.valid" :data-level="cell.level" :aria-pressed="picked===cell.date" :aria-label="`${cell.date}，${duration(cell.seconds)}，查看详情`" :title="`${cell.date} · ${duration(cell.seconds)}`" @click="picked=cell.date;detail=true"/></div></div></div>
  <div class="pt-legend"><span>少</span><i v-for="n in [0,1,2,3,4]" :key="n" class="pt-level" :data-level="n"/><span>多</span></div>
  <div class="pt-selection"><span>{{picked}}<small>{{data?duration(day?.seconds||0):'暂无记录'}}</small></span><button class="soft-button" @click="detail=true"><Icon name="clock"/>在线详情</button></div><p class="pt-hint">{{source==='local'?'本机实际运行游戏的时长，不参与积分结算。':'服务器核验记录参加周榜，跨服同时在线不重复计时。'}}</p>
 </section>
 <AppOverlay :open="detail" :label="picked+' · 在线详情'" @close="detail=false"><section class="sheet"><header class="sheet-header"><h2>{{picked}} · {{source==='local'?'游玩详情':'在线详情'}}</h2><button class="icon-button" aria-label="关闭详情" @click="detail=false"><Icon name="close"/></button></header><div class="sheet-body pt-detail"><h3>共 {{duration(source==='server'?(detailData?.seconds??day?.seconds??0):day?.seconds||0)}}</h3><p v-if="source==='local'" class="pt-hint">本机按日累计游戏运行时长，最多延迟 30 秒写入，不包含安装准备时间。此记录不等同于服务器在线。</p><template v-else><p class="pt-hint">计入周榜 {{duration(detailData?.eligibleSeconds??day?.eligibleSeconds??0)}} · 北京时间</p><div v-if="detailError" class="pt-alert">{{detailError}}<button class="soft-button" @click="loadDetail">重试</button></div><p v-if="detailLoading">正在读取在线记录…</p><ul v-else class="pt-sessions"><li v-for="session in detailData?.sessions||[]" :key="session.start"><span>{{clock(session.start)}} — {{clock(session.end)}}</span><small>{{duration(session.seconds)}}</small></li></ul><p v-if="!detailLoading&&!detailError&&!detailData?.sessions?.length" class="pt-hint">当天还没有服务器核验的在线记录。</p><p class="pt-hint">断连期间不补记，多个服务器重叠的时间已合并。</p></template></div></section></AppOverlay>
 <AppOverlay :open="board" label="每周在线时长榜" @close="board=false"><section class="sheet"><header class="sheet-header"><h2>每周在线时长榜</h2><button class="icon-button" aria-label="关闭时长榜" @click="board=false"><Icon name="close"/></button></header><div class="sheet-body pt-board"><p v-if="!loggedIn">连接社区后查看周榜。</p><template v-else><div class="pt-toolbar"><AppSelect :model-value="ranking?.week||week" label="选择统计周" :options="ranking?.weeks?.map(v=>({value:v.week,label:v.label+(v.settled?' · 已结算':'')}))||[{value:week,label:'本周'}]" @update:model-value="week=Number($event)"/><button class="icon-button" aria-label="刷新每周时长榜" :disabled="boardLoading" @click="loadBoard"><Icon name="refresh"/></button></div><div v-if="boardError" class="pt-alert">{{boardError}}<button class="soft-button" @click="loadBoard">重试</button></div><p v-if="boardLoading&&!ranking">正在读取周榜…</p><template v-if="ranking"><div class="pt-board-me">{{ranking.self?`我的排名 #${ranking.self.rank} · ${duration(ranking.self.seconds)} · ${ranking.settled?'已获得':'预计'} ${ranking.self.reward} 积分`:'本周还没有可排名的核验记录'}}{{!ranking.settled?' · 每周一自动结算':''}}</div><div class="pt-board-list"><div v-for="item in ranking.items" :key="item.uid" class="pt-board-row" :class="{self:item.uid===state.selectedProfile?.id}"><span>{{item.rank}}</span><div><strong>{{item.name}}</strong><small>{{duration(item.seconds)}}{{!item.eligible?' · 未达最低时长':''}}</small></div><b>+{{item.reward}} 分</b></div></div><p v-if="!ranking.items.length" class="pt-hint">这一周还没有在线记录，进入默认服务器一起玩吧。</p><div class="pt-board-rules">{{ranking.rules.enabled?'周榜奖励已开启':'周榜奖励已关闭'}} · 每周至少 {{ranking.rules.minWeeklyMinutes}} 分钟 · 每日最多计入 {{ranking.rules.dailyCapMinutes}} 分钟。奖励按管理员为本周配置的名次发放，已结算记录不随新规则改变。<br/>{{ranking.verification}}</div></template></template></div></section></AppOverlay>
</template>
<style scoped>
.mobile-play-calendar h2{font-size:1rem;margin:0}.calendar-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.mobile-play-calendar .pt-grid button{min-height:0;min-width:0}.mobile-play-calendar .pt-tabs{align-self:start}.mobile-play-calendar .pt-tabs button{min-height:44px}.mobile-play-calendar .pt-heat{grid-template-rows:20px 156px}.calendar-actions>.soft-button,.pt-selection>.soft-button{min-height:44px}.pt-board>.pt-toolbar{flex-wrap:nowrap}.pt-board .app-select{min-width:0;flex:1}.pt-board .icon-button{flex:none}.pt-board-list{max-height:none}.pt-sessions{max-height:none}.pt-board-row{grid-template-columns:24px minmax(0,1fr) auto;gap:8px}.pt-board,.pt-detail{color:var(--ink)}
</style>
